CREATE TABLE public.planning_external_people (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(email=lower(btrim(email))), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.planning_external_people TO service_role;
ALTER TABLE public.planning_external_people ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.planning_external_participants ADD COLUMN external_person_id uuid REFERENCES public.planning_external_people(id);
INSERT INTO public.planning_external_people(email) SELECT DISTINCT lower(btrim(email)) FROM public.planning_external_participants ON CONFLICT DO NOTHING;
UPDATE public.planning_external_participants e SET external_person_id=p.id FROM public.planning_external_people p WHERE p.email=lower(btrim(e.email));
CREATE FUNCTION public.planning_bind_external_person() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.email:=lower(btrim(NEW.email)); INSERT INTO public.planning_external_people(email) VALUES(NEW.email) ON CONFLICT DO NOTHING; SELECT id INTO NEW.external_person_id FROM public.planning_external_people WHERE email=NEW.email; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.planning_bind_external_person() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER planning_bind_external_person BEFORE INSERT OR UPDATE OF email ON public.planning_external_participants FOR EACH ROW EXECUTE FUNCTION public.planning_bind_external_person();
CREATE TABLE public.planning_external_portal_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES public.planning_external_people(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.planning_external_portal_sessions TO service_role;
ALTER TABLE public.planning_external_portal_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.planning_external_login_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES public.planning_external_participants(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '48 hours', used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.planning_external_login_links TO service_role;
ALTER TABLE public.planning_external_login_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.planning_external_sessions ADD COLUMN portal_session_id uuid REFERENCES public.planning_external_portal_sessions(id);
CREATE FUNCTION public.planning_external_portal_person(_token text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT person_id FROM public.planning_external_portal_sessions WHERE length(_token)>=40 AND token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND expires_at>now() $$;
REVOKE ALL ON FUNCTION public.planning_external_portal_person(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.planning_external_portal_mint(_person uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t text:=encode(extensions.gen_random_bytes(32),'hex'); BEGIN INSERT INTO public.planning_external_portal_sessions(person_id,token_hash) VALUES(_person,encode(extensions.digest(t,'sha256'),'hex')); RETURN t; END $$;
REVOKE ALL ON FUNCTION public.planning_external_portal_mint(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.planning_external_portal_upgrade(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; t text; BEGIN e:=public.planning_external_identity(_token); IF e.id IS NULL OR e.external_person_id IS NULL THEN RAISE EXCEPTION 'Logg inn på nytt' USING ERRCODE='42501'; END IF; t:=public.planning_external_portal_mint(e.external_person_id); RETURN jsonb_build_object('portal_token',t); END $$;
CREATE FUNCTION public.planning_external_prepare_login(_participant_id uuid DEFAULT NULL,_email text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; t text; BEGIN
IF _participant_id IS NOT NULL THEN SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.id=_participant_id AND ep.deleted_at IS NULL AND p.deleted_at IS NULL AND ep.status IN ('active','pending','sent','send_failed');
ELSE SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.email=lower(btrim(_email)) AND ep.deleted_at IS NULL AND p.deleted_at IS NULL AND ep.status='active' ORDER BY ep.accepted_at DESC LIMIT 1; END IF;
IF e.id IS NULL THEN RETURN NULL; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(e.external_person_id::text,42));
IF EXISTS(SELECT 1 FROM public.planning_external_login_links l JOIN public.planning_external_participants ep ON ep.id=l.participant_id WHERE ep.external_person_id=e.external_person_id AND l.created_at>now()-interval '2 minutes') THEN RETURN NULL; END IF;
IF (SELECT count(*) FROM public.planning_external_login_links l JOIN public.planning_external_participants ep ON ep.id=l.participant_id WHERE ep.external_person_id=e.external_person_id AND l.created_at>now()-interval '1 hour')>=5 THEN RETURN NULL; END IF;
t:=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.planning_external_login_links(participant_id,token_hash) VALUES(e.id,encode(extensions.digest(t,'sha256'),'hex'));
RETURN jsonb_build_object('link_id',(SELECT id FROM public.planning_external_login_links WHERE token_hash=encode(extensions.digest(t,'sha256'),'hex')),'id',e.id,'token',t,'name',e.name,'email',e.email,'participant_type',e.participant_type,'project_name',(SELECT name FROM public.planning_projects WHERE id=e.planning_project_id),'project_id',e.planning_project_id); END $$;
REVOKE ALL ON FUNCTION public.planning_external_prepare_login(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.planning_external_prepare_login(uuid,text) TO service_role;
CREATE FUNCTION public.planning_external_accept_login(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.planning_external_login_links; e public.planning_external_participants; t text; BEGIN
SELECT * INTO l FROM public.planning_external_login_links WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND length(_token)>=40 AND used_at IS NULL AND expires_at>now() FOR UPDATE;
SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.id=l.participant_id AND ep.status IN ('active','pending','sent','send_failed') AND ep.deleted_at IS NULL AND p.deleted_at IS NULL FOR UPDATE OF ep;
IF l.id IS NULL OR e.id IS NULL THEN RAISE EXCEPTION 'Lenken er utløpt eller brukt. Be om en ny tilgangslenke.' USING ERRCODE='42501'; END IF;
UPDATE public.planning_external_login_links SET used_at=now() WHERE id=l.id;
UPDATE public.planning_external_participants SET status='active',accepted_at=coalesce(accepted_at,now()),invite_hash=NULL WHERE id=e.id;
t:=public.planning_external_portal_mint(e.external_person_id);
RETURN jsonb_build_object('portal_token',t,'project_id',e.planning_project_id); END $$;
CREATE FUNCTION public.planning_external_my_projects(_token text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE person uuid; result jsonb; BEGIN person:=public.planning_external_portal_person(_token); IF person IS NULL THEN RAISE EXCEPTION 'Logg inn på nytt' USING ERRCODE='42501'; END IF;
SELECT jsonb_build_object('person',jsonb_build_object('email',x.email,'name',coalesce((SELECT ep.name FROM public.planning_external_participants ep WHERE ep.external_person_id=x.id AND ep.status='active' AND ep.deleted_at IS NULL ORDER BY ep.accepted_at DESC LIMIT 1),'')), 'projects',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'status',p.status,'participant_type',e.participant_type,'company_name',e.company_name,'project_number',(SELECT nullif(btrim(src.project_number),'') FROM public.events src WHERE src.id=p.financial_project_id AND src.company_id=p.company_id AND src.entity_type='financial_project' AND src.deleted_at IS NULL AND public.has_active_tripletex_project_link(src.id,src.company_id))) ORDER BY p.name) FROM public.planning_external_participants e JOIN public.planning_projects p ON p.id=e.planning_project_id WHERE e.external_person_id=x.id AND e.status='active' AND e.deleted_at IS NULL AND p.deleted_at IS NULL),'[]'::jsonb)) INTO result FROM public.planning_external_people x WHERE x.id=person; RETURN result; END $$;
CREATE FUNCTION public.planning_external_open_project(_token text,_project_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person uuid; e public.planning_external_participants; s public.planning_external_portal_sessions; t text; BEGIN
person:=public.planning_external_portal_person(_token); IF person IS NULL OR _project_id IS NULL THEN RAISE EXCEPTION 'Ingen tilgang til prosjektet' USING ERRCODE='42501'; END IF;
SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.external_person_id=person AND ep.planning_project_id=_project_id AND ep.status='active' AND ep.deleted_at IS NULL AND p.deleted_at IS NULL;
IF e.id IS NULL THEN RAISE EXCEPTION 'Ingen tilgang til prosjektet' USING ERRCODE='42501'; END IF;
SELECT * INTO s FROM public.planning_external_portal_sessions WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND expires_at>now();
t:=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.planning_external_sessions(participant_id,token_hash,expires_at,portal_session_id) VALUES(e.id,encode(extensions.digest(t,'sha256'),'hex'),least(s.expires_at,now()+interval '1 hour'),s.id);
RETURN jsonb_build_object('session_token',t); END $$;
CREATE OR REPLACE FUNCTION public.planning_external_identity(_token text) RETURNS public.planning_external_participants LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e FROM public.planning_external_sessions s JOIN public.planning_external_participants e ON e.id=s.participant_id JOIN public.planning_projects p ON p.id=e.planning_project_id LEFT JOIN public.planning_external_portal_sessions ps ON ps.id=s.portal_session_id WHERE s.token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND length(_token)>=40 AND s.expires_at>now() AND e.status='active' AND e.deleted_at IS NULL AND p.deleted_at IS NULL AND (s.portal_session_id IS NULL OR (ps.expires_at>now() AND ps.person_id=e.external_person_id)) LIMIT 1 $$;
CREATE FUNCTION public.planning_external_portal_logout(_token text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.planning_external_portal_sessions SET expires_at=now() WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND length(_token)>=40; END $$;
REVOKE ALL ON FUNCTION public.planning_external_portal_upgrade(text),public.planning_external_accept_login(text),public.planning_external_my_projects(text),public.planning_external_open_project(text,uuid),public.planning_external_portal_logout(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.planning_external_portal_upgrade(text),public.planning_external_accept_login(text),public.planning_external_my_projects(text),public.planning_external_open_project(text,uuid),public.planning_external_portal_logout(text) TO anon,authenticated;
COMMENT ON TABLE public.planning_external_people IS 'Verified email-only external identity, not a Hub account; active explicit project participants remain the sole grant source.';